<?php session_start();require_once __DIR__.'/../config/database.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$st=$pdo->prepare('SELECT * FROM admins WHERE username=? LIMIT 1');$st->execute([trim($_POST['username']??'')]);$a=$st->fetch(PDO::FETCH_ASSOC);if($a&&password_verify($_POST['password']??'',$a['password'])){$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];header('Location:index.php');exit;}$error='ইউজারনেম অথবা পাসওয়ার্ড সঠিক নয়।';}?><!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link href="https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="style.css"><title>Admin Login</title></head><body class="login-page"><form method="post" class="login-card"><h1>🌿 Admin Panel</h1><p>ভেষজ উন্নয়ন ফাউন্ডেশন</p><?php if($error):?><div class="alert"><?=htmlspecialchars($error)?></div><?php endif;?><input name="username" placeholder="Username" required><input type="password" name="password" placeholder="Password" required><button>Login করুন</button><small>প্রাথমিক Login: admin / admin123</small></form></body></html>